{
  "name": "@b00dea/cockpit",
  "version": "0.1.14",
  "cockpitSourceRevision": "109c69834a7fdef2ab8e4938bc89b8ec6bc66a1b",
  "type": "module",
  "description": "The local environment coding agents work from: every repository of your product in reach, its Compose stack running on the live checkouts, one guard and instruction set for Claude Code, Codex CLI and OpenCode, and work orders checked against criteria you set.",
  "keywords": [
    "ai-agents",
    "coding-agents",
    "claude-code",
    "codex",
    "opencode",
    "docker-compose",
    "developer-environment",
    "multi-repo",
    "agents-md",
    "agent-skills",
    "guardrails",
    "cli"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/b0dea/cockpit.git",
    "directory": "packages/cockpit"
  },
  "homepage": "https://github.com/b0dea/cockpit#readme",
  "bugs": {
    "url": "https://github.com/b0dea/cockpit/issues"
  },
  "types": "./dist/cli.d.ts",
  "exports": {
    ".": {
      "types": "./dist/cli.d.ts",
      "import": "./dist/cli.js"
    }
  },
  "bin": {
    "cockpit": "bin/cockpit.mjs"
  },
  "scripts": {
    "build": "node ../../scripts/build-cockpit.ts",
    "bundle:rulesync": "node scripts/build-rulesync-generator.mjs",
    "bundle:rulesync:check": "node scripts/build-rulesync-generator.mjs --check",
    "schema": "node --input-type=module --eval \"import { writeFile } from 'node:fs/promises'; import { renderCockpitSchema } from './dist/schema-json.js'; await writeFile('./cockpit.schema.json', renderCockpitSchema())\"",
    "schema:check": "node --input-type=module --eval \"import { readFile } from 'node:fs/promises'; import { renderCockpitSchema } from './dist/schema-json.js'; const artifact = process.argv[1] ?? './cockpit.schema.json'; if (await readFile(artifact, 'utf8') !== renderCockpitSchema()) { console.error('[COCKPIT_SCHEMA_STALE] cockpit.schema.json differs from the runtime schema; run npm run schema'); process.exitCode = 1 }\"",
    "prepack": "npm run bundle:rulesync:check && npm run build && npm run schema:check"
  },
  "files": [
    "bin",
    "dist",
    "docs",
    "libexec",
    "surfaces",
    "cockpit.schema.json",
    "CHANGELOG.md",
    "LICENSE",
    "README.md"
  ],
  "os": [
    "darwin",
    "linux"
  ],
  "engines": {
    "node": "^22.22.0 || ^24.0.0 || ^26.0.0"
  },
  "dependencies": {
    "smol-toml": "1.9.1",
    "yaml": "2.9.1",
    "zod": "4.6.7"
  },
  "devDependencies": {
    "esbuild": "0.28.2",
    "rulesync": "43.4.2"
  }
}

{
  "format": "cockpit-restriction-adapter/v1",
  "target": "opencode",
  "mechanism": "native",
  "promptTier": false,
  "measuredOn": "2026-08-24",
  "measuredVersion": "1.18.15",
  "provenance": "paired native tool.execute.before payload, apply_patch and thrown-refusal probe",
  "registration": {
    "kind": "opencode-plugin",
    "path": ".opencode/plugin/cockpit-guards.js",
    "event": "tool.execute.before",
    "matcher": "bash|edit|write|apply_patch"
  },
  "payload": {
    "kind": "opencode-before",
    "bashTool": "bash",
    "editTools": ["edit", "write", "apply_patch"]
  },
  "readonly": {
    "kind": "agent-frontmatter",
    "pathPattern": ".opencode/agents/{agent}.md",
    "bytes": "permission:\n  edit: deny\n"
  }
}
